//! P1-15.3 (WP-43): vec3/vec4 golden comparison against the C ref-dump.
//!
//! `test/golden/ref-dump/math.golden` is generated by `test/ref-dump`
//! (obs-ref-dump, pinned 33.0.1 C sources): 32 seeded splitmix64 cases per
//! function (seed 0x0B5, stream is platform-independent), floats printed
//! with `%.9g` — which round-trips f32 exactly (9 significant digits).
//!
//! This test re-runs every `math/vec3_*` and `math/vec4_*` group through
//! the Rust port and compares at the spec tolerance (relative **or**
//! absolute 1e-6); the int results of `*_close` compare exactly.
//!
//! The trailing `# section: rand` groups are excluded: they are driven by
//! libc `rand()` (the stream is platform-dependent, and the Rust
//! `vec3_rand` uses its own deterministic PRNG — different inputs, so no
//! value comparison is possible; the section's purpose is C-side coverage
//! and the CI golden-diff strips it).
//!
//! Gating: the golden is committed to the repo, so the test always runs.

use obs_math::matrix3::Matrix3;
use obs_math::matrix4::Matrix4;
use obs_math::plane::Plane;
use obs_math::vec3::{
    self as v3, Vec3, vec3_close, vec3_cross, vec3_dist, vec3_dot, vec3_from_vec4, vec3_mirror,
    vec3_mirrorv, vec3_neg, vec3_norm, vec3_plane_dist, vec3_rotate, vec3_transform,
    vec3_transform3x4,
};
use obs_math::vec4::{
    self as v4, Vec4, vec4_close, vec4_copy, vec4_dist, vec4_dot, vec4_from_bgra, vec4_from_rgba,
    vec4_from_rgba_srgb, vec4_from_vec3, vec4_neg, vec4_norm, vec4_transform,
};

const GOLDEN: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../test/golden/ref-dump/math.golden"
);
/// The spec tolerance (S-008 §2, P1-15.3 Done-when): 1e-6 relative or absolute.
const TOL: f64 = 1e-6;
/// Seeded cases per function in the ref-dump (CASES in ref-dump-math.c).
const CASES: usize = 32;

#[derive(Debug)]
enum T {
    N(f64),
    H(u32),
    G(String, Vec<T>),
}

/// Recursive-descent parser for the golden's `label(v1 v2 ...)` argument
/// and result notation. Numbers parse as f64 (the `%.9g` text), hex args
/// as u32, labels as groups; `label=value` becomes `G(label, [N(value)])`;
/// a bare `(v1 ...)` is a group with the empty label.
fn parse_items(s: &mut &str) -> Vec<T> {
    let mut out = Vec::new();
    loop {
        *s = s.trim_start();
        if s.is_empty() || s.starts_with(')') {
            break;
        }
        if let Some(h) = s.strip_prefix("0x") {
            let end = h.find(|c: char| !c.is_ascii_hexdigit()).unwrap_or(h.len());
            let v = u32::from_str_radix(&h[..end], 16).expect("hex arg");
            *s = &h[end..];
            out.push(T::H(v));
            continue;
        }
        let bytes = s.as_bytes();
        let c = bytes[0];
        if c == b'-' || c == b'+' || c.is_ascii_digit() || c == b'.' {
            let mut end = 1;
            while end < bytes.len() {
                let b = bytes[end];
                if b.is_ascii_digit()
                    || b == b'.'
                    || b == b'e'
                    || b == b'E'
                    || ((b == b'+' || b == b'-')
                        && (bytes[end - 1] == b'e' || bytes[end - 1] == b'E'))
                {
                    end += 1;
                } else {
                    break;
                }
            }
            let tok = &s[..end];
            *s = &s[end..];
            out.push(T::N(tok.parse::<f64>().expect("number arg")));
            continue;
        }
        let mut end = 0;
        while end < s.len() && s.as_bytes()[end].is_ascii_alphanumeric() {
            end += 1;
        }
        let label = &s[..end];
        *s = &s[end..];
        *s = s.trim_start();
        if let Some(rest) = s.strip_prefix('(') {
            *s = rest;
            let items = parse_items(s);
            *s = s.trim_start();
            assert!(s.starts_with(')'), "unbalanced ) in group {label:?}: {s:?}");
            *s = &s[1..];
            out.push(T::G(label.to_string(), items));
        } else if let Some(rest) = s.strip_prefix('=') {
            *s = rest;
            let items = parse_items(s);
            assert_eq!(items.len(), 1, "label=value must take one number: {label}");
            out.push(T::G(label.to_string(), items));
        } else {
            panic!("unexpected token after label {label:?}: {s:?}");
        }
    }
    out
}

fn group<'x>(items: &'x [T], label: &str) -> &'x [T] {
    items
        .iter()
        .find_map(|t| match t {
            T::G(l, v) if l == label => Some(v.as_slice()),
            _ => None,
        })
        .unwrap_or_else(|| panic!("missing arg {label:?}: {items:?}"))
}

fn f_of(items: &[T], i: usize) -> f32 {
    match items.get(i) {
        Some(T::N(f)) => *f as f32,
        other => panic!("expected number at {i}, got {other:?}"),
    }
}

fn vec3_of(items: &[T], label: &str) -> Vec3 {
    let g = group(items, label);
    Vec3 {
        x: f_of(g, 0),
        y: f_of(g, 1),
        z: f_of(g, 2),
        // the ref-dump's rv3() always keeps w = 0 (the C padding lane)
        w: 0.0,
    }
}

fn vec4_of(items: &[T], label: &str) -> Vec4 {
    let g = group(items, label);
    Vec4 {
        x: f_of(g, 0),
        y: f_of(g, 1),
        z: f_of(g, 2),
        w: f_of(g, 3),
    }
}

fn matrix3_of(items: &[T]) -> Matrix3 {
    let m = group(items, "m");
    let row = |l: &str| {
        let g = group(m, l);
        v3::vec3_set(f_of(g, 0), f_of(g, 1), f_of(g, 2))
    };
    Matrix3 {
        x: row("x"),
        y: row("y"),
        z: row("z"),
        t: row("t"),
    }
}

fn matrix4_of(items: &[T]) -> Matrix4 {
    let m = group(items, "m");
    let row = |l: &str| {
        let g = group(m, l);
        v4::vec4_set(f_of(g, 0), f_of(g, 1), f_of(g, 2), f_of(g, 3))
    };
    Matrix4 {
        x: row("x"),
        y: row("y"),
        z: row("z"),
        t: row("t"),
    }
}

fn plane_of(items: &[T]) -> Plane {
    let p = group(items, "p");
    Plane {
        dir: vec3_of(p, "dir"),
        dist: f_of(group(p, "dist"), 0),
    }
}

fn hex_of(items: &[T]) -> u32 {
    match items.first() {
        Some(T::H(h)) => *h,
        other => panic!("expected hex arg, got {other:?}"),
    }
}

/// Flatten the result side to f32 values (matrix results carry labeled
/// rows; the `*_close` int result parses as a whole N).
fn results_of(res: &[T]) -> Vec<f32> {
    let mut out = Vec::new();
    results_into(res, &mut out);
    out
}

fn results_into(items: &[T], out: &mut Vec<f32>) {
    for t in items {
        match t {
            T::N(f) => out.push(*f as f32),
            T::G(_, sub) => results_into(sub, out),
            T::H(_) => panic!("hex on the result side"),
        }
    }
}

fn check(group_name: &str, case: usize, expected: &[f32], actual: &[f32]) {
    assert_eq!(
        expected.len(),
        actual.len(),
        "{group_name} case {case}: arity"
    );
    for (i, (e, a)) in expected.iter().zip(actual).enumerate() {
        let (e, a) = (*e as f64, *a as f64);
        let ok = (e - a).abs() <= TOL * 1.0_f64.max(e.abs().max(a.abs()));
        assert!(
            ok,
            "{group_name} case {case} lane {i}: expected {e}, got {a}"
        );
    }
}

/// Dispatch one golden group through the Rust port; returns the result
/// lanes (the caller compares them against the golden).
fn run_vec3(name: &str, args: &[T]) -> Vec<f32> {
    let lanes = |v: &Vec3| vec![v.x, v.y, v.z];
    match name {
        "vec3_zero" => lanes(&v3::vec3_zero()),
        "vec3_set" => lanes(&v3::vec3_set(
            f_of(group(args, ""), 0),
            f_of(group(args, ""), 1),
            f_of(group(args, ""), 2),
        )),
        "vec3_copy" => {
            let mut d = v3::vec3_zero();
            v3::vec3_copy(&mut d, &vec3_of(args, ""));
            lanes(&d)
        }
        "vec3_from_vec4" => lanes(&vec3_from_vec4(&vec4_of(args, "v4"))),
        "vec3_add" => lanes(&v3::vec3_add(&vec3_of(args, "a"), &vec3_of(args, "b"))),
        "vec3_sub" => lanes(&v3::vec3_sub(&vec3_of(args, "a"), &vec3_of(args, "b"))),
        "vec3_mul" => lanes(&v3::vec3_mul(&vec3_of(args, "a"), &vec3_of(args, "b"))),
        "vec3_div" => lanes(&v3::vec3_div(&vec3_of(args, "a"), &vec3_of(args, "b"))),
        "vec3_addf" => lanes(&v3::vec3_addf(
            &vec3_of(args, "v"),
            f_of(group(args, "f"), 0),
        )),
        "vec3_subf" => lanes(&v3::vec3_subf(
            &vec3_of(args, "v"),
            f_of(group(args, "f"), 0),
        )),
        "vec3_mulf" => lanes(&v3::vec3_mulf(
            &vec3_of(args, "v"),
            f_of(group(args, "f"), 0),
        )),
        "vec3_divf" => lanes(&v3::vec3_divf(
            &vec3_of(args, "v"),
            f_of(group(args, "f"), 0),
        )),
        "vec3_dot" => vec![vec3_dot(&vec3_of(args, "a"), &vec3_of(args, "b"))],
        "vec3_cross" => lanes(&vec3_cross(&vec3_of(args, "a"), &vec3_of(args, "b"))),
        "vec3_neg" => lanes(&vec3_neg(&vec3_of(args, "v"))),
        "vec3_len" => vec![v3::vec3_len(&vec3_of(args, "v"))],
        "vec3_dist" => vec![vec3_dist(&vec3_of(args, "a"), &vec3_of(args, "b"))],
        "vec3_norm" => lanes(&vec3_norm(&vec3_of(args, "v"))),
        "vec3_close" => vec![f64::from(vec3_close(
            &vec3_of(args, "a"),
            &vec3_of(args, "b"),
            f_of(group(args, "eps"), 0),
        )) as f32],
        "vec3_min" => lanes(&v3::vec3_min(&vec3_of(args, "v"), &vec3_of(args, "min"))),
        "vec3_minf" => lanes(&v3::vec3_minf(
            &vec3_of(args, "v"),
            f_of(group(args, "f"), 0),
        )),
        "vec3_max" => lanes(&v3::vec3_max(&vec3_of(args, "v"), &vec3_of(args, "max"))),
        "vec3_maxf" => lanes(&v3::vec3_maxf(
            &vec3_of(args, "v"),
            f_of(group(args, "f"), 0),
        )),
        "vec3_abs" => lanes(&v3::vec3_abs(&vec3_of(args, "v"))),
        "vec3_floor" => lanes(&v3::vec3_floor(&vec3_of(args, "v"))),
        "vec3_ceil" => lanes(&v3::vec3_ceil(&vec3_of(args, "v"))),
        "vec3_plane_dist" => vec![vec3_plane_dist(&vec3_of(args, "v"), &plane_of(args))],
        "vec3_transform" => lanes(&vec3_transform(&vec3_of(args, "v"), &matrix4_of(args))),
        "vec3_rotate" => lanes(&vec3_rotate(&vec3_of(args, "v"), &matrix3_of(args))),
        "vec3_transform3x4" => lanes(&vec3_transform3x4(&vec3_of(args, "v"), &matrix3_of(args))),
        "vec3_mirror" => lanes(&vec3_mirror(&vec3_of(args, "v"), &plane_of(args))),
        "vec3_mirrorv" => lanes(&vec3_mirrorv(&vec3_of(args, "v"), &vec3_of(args, "vec"))),
        other => panic!("unhandled vec3 group {other}"),
    }
}

fn run_vec4(name: &str, args: &[T]) -> Vec<f32> {
    let lanes = |v: &Vec4| vec![v.x, v.y, v.z, v.w];
    match name {
        "vec4_zero" => lanes(&v4::vec4_zero()),
        "vec4_set" => {
            let g = group(args, "");
            lanes(&v4::vec4_set(
                f_of(g, 0),
                f_of(g, 1),
                f_of(g, 2),
                f_of(g, 3),
            ))
        }
        "vec4_copy" => {
            let mut d = v4::vec4_zero();
            vec4_copy(&mut d, &vec4_of(args, ""));
            lanes(&d)
        }
        "vec4_from_vec3" => lanes(&vec4_from_vec3(&vec3_of(args, "v3"))),
        "vec4_add" => lanes(&v4::vec4_add(&vec4_of(args, "a"), &vec4_of(args, "b"))),
        "vec4_sub" => lanes(&v4::vec4_sub(&vec4_of(args, "a"), &vec4_of(args, "b"))),
        "vec4_mul" => lanes(&v4::vec4_mul(&vec4_of(args, "a"), &vec4_of(args, "b"))),
        "vec4_div" => lanes(&v4::vec4_div(&vec4_of(args, "a"), &vec4_of(args, "b"))),
        "vec4_addf" => lanes(&v4::vec4_addf(
            &vec4_of(args, "v"),
            f_of(group(args, "f"), 0),
        )),
        "vec4_subf" => lanes(&v4::vec4_subf(
            &vec4_of(args, "v"),
            f_of(group(args, "f"), 0),
        )),
        "vec4_mulf" => lanes(&v4::vec4_mulf(
            &vec4_of(args, "v"),
            f_of(group(args, "f"), 0),
        )),
        "vec4_divf" => lanes(&v4::vec4_divf(
            &vec4_of(args, "v"),
            f_of(group(args, "f"), 0),
        )),
        "vec4_dot" => vec![vec4_dot(&vec4_of(args, "a"), &vec4_of(args, "b"))],
        "vec4_neg" => lanes(&vec4_neg(&vec4_of(args, "v"))),
        "vec4_len" => vec![v4::vec4_len(&vec4_of(args, "v"))],
        "vec4_dist" => vec![vec4_dist(&vec4_of(args, "a"), &vec4_of(args, "b"))],
        "vec4_norm" => lanes(&vec4_norm(&vec4_of(args, "v"))),
        "vec4_close" => vec![f64::from(vec4_close(
            &vec4_of(args, "a"),
            &vec4_of(args, "b"),
            f_of(group(args, "eps"), 0),
        )) as f32],
        "vec4_min" => lanes(&v4::vec4_min(&vec4_of(args, "v"), &vec4_of(args, "min"))),
        "vec4_minf" => lanes(&v4::vec4_minf(
            &vec4_of(args, "v"),
            f_of(group(args, "f"), 0),
        )),
        "vec4_max" => lanes(&v4::vec4_max(&vec4_of(args, "v"), &vec4_of(args, "max"))),
        "vec4_maxf" => lanes(&v4::vec4_maxf(
            &vec4_of(args, "v"),
            f_of(group(args, "f"), 0),
        )),
        "vec4_abs" => lanes(&v4::vec4_abs(&vec4_of(args, "v"))),
        "vec4_floor" => lanes(&v4::vec4_floor(&vec4_of(args, "v"))),
        "vec4_ceil" => lanes(&v4::vec4_ceil(&vec4_of(args, "v"))),
        "vec4_from_rgba" => {
            let mut d = v4::vec4_zero();
            vec4_from_rgba(&mut d, hex_of(args));
            lanes(&d)
        }
        "vec4_from_bgra" => {
            let mut d = v4::vec4_zero();
            vec4_from_bgra(&mut d, hex_of(args));
            lanes(&d)
        }
        "vec4_from_rgba_srgb" => {
            let mut d = v4::vec4_zero();
            vec4_from_rgba_srgb(&mut d, hex_of(args));
            lanes(&d)
        }
        "vec4_transform" => lanes(&vec4_transform(&vec4_of(args, "v"), &matrix4_of(args))),
        other => panic!("unhandled vec4 group {other}"),
    }
}

/// `case 12: a(1 2 3) -> 4` → (12, "a(1 2 3)", "4"); zero-arg cases
/// carry an empty argspec (`case 0: -> 0 0`).
fn split_case(line: &str) -> (usize, &str, &str) {
    let body = line
        .strip_prefix("case ")
        .unwrap_or_else(|| panic!("not a case line: {line:?}"));
    let (n, rest) = body
        .split_once(':')
        .unwrap_or_else(|| panic!("no case colon: {line:?}"));
    let n: usize = n
        .parse()
        .unwrap_or_else(|_| panic!("bad case number: {line:?}"));
    let (argspec, resspec) = rest
        .split_once(" -> ")
        .unwrap_or_else(|| panic!("no result arrow: {line:?}"));
    (n, argspec.trim_start(), resspec.trim_start())
}

#[test]
fn vec3_vec4_match_c_refdump_golden() {
    let text = std::fs::read_to_string(GOLDEN).expect("committed math golden");

    // Split into (group name, [case lines]); case lines attach to the
    // most recent group, and the libc-rand section is skipped.
    let mut groups: Vec<(String, Vec<(usize, String)>)> = Vec::new();
    let mut in_rand = false;
    for line in text.lines() {
        if line.starts_with("# section: rand") {
            in_rand = true;
            continue;
        }
        if let Some(h) = line.strip_prefix("# math/") {
            groups.push((h.trim().to_string(), Vec::new()));
            continue;
        }
        if line.starts_with('#') || in_rand || !line.starts_with("case ") {
            // the matrix4_inv group carries ` result:` continuation lines —
            // they belong to no vec3/vec4 group and are skipped
            continue;
        }
        if let Some((_, cases)) = groups.last_mut() {
            let (n, _args, _res) = split_case(line);
            cases.push((n, line.to_string()));
        }
    }

    let mut checked = 0usize;
    let mut groups_done = 0usize;
    for (name, cases) in &groups {
        // 32 vec3 + 29 vec4 groups; the `vec3_rand *` rand-section groups
        // carry a space in the name and are skipped with everything else.
        if !(name.starts_with("vec3_") || name.starts_with("vec4_")) || name.contains(' ') {
            continue;
        }
        groups_done += 1;
        assert_eq!(cases.len(), CASES, "{name}: {CASES} seeded cases expected");
        for (n, line) in cases {
            let (case, argspec, resspec) = split_case(line);
            assert_eq!(*n, case);
            let mut a = argspec;
            let mut r = resspec;
            let args = parse_items(&mut a);
            let res = parse_items(&mut r);
            let expected = results_of(&res);
            let actual = if name.starts_with("vec3_") {
                run_vec3(name, &args)
            } else {
                run_vec4(name, &args)
            };
            check(name, *n, &expected, &actual);
            checked += 1;
        }
    }

    assert_eq!(
        groups_done, 61,
        "all 61 vec3/vec4 golden groups must be covered"
    );
    assert_eq!(checked, 61 * CASES, "every seeded case compared");
    eprintln!("golden ref-dump: {checked} vec3/vec4 cases match the C golden (tol 1e-6)");
}
